function dreamPlayerPoint(){return{x:120+(player.x-82)/788*720,y:375+(player.y-195)/370*185};}
function getNearest(){let best=null,dist=105,p=roomPrefs.activeSpace==='dream'?dreamPlayerPoint():player,list=roomPrefs.activeSpace==='dream'?dreamObjects:objects;for(const o of list){const dx=Math.max(o.x-p.x,0,p.x-(o.x+o.w)),dy=Math.max(o.y-p.y,0,p.y-(o.y+o.h)),d=Math.hypot(dx,dy);if(d<dist){best=o;dist=d;}}return best;}
function blocked(x,y){return objects.some(o=>x>o.x-10&&x<o.x+o.w+10&&y>o.y-5&&y<o.y+o.h+12);}
function move(dx,dy,dt){if(!dx&&!dy)return;if(posture!=='stand')standUp();const nx=Math.min(870,Math.max(82,player.x+dx*dt*245)),ny=Math.min(565,Math.max(195,player.y+dy*dt*245));if(roomPrefs.activeSpace==='dream'){player.x=nx;player.y=ny;}else{if(!blocked(nx,player.y))player.x=nx;if(!blocked(player.x,ny))player.y=ny;}walk+=dt;}
function frame(t){const dt=Math.min((t-last)/1000||0,.04);last=t;window.lifeRoomMotion?.prepare();if(!$('#panel').open&&!lifeDialog.open&&!roomEditing&&lifePage==='room'){let dx=(keys.has('arrowright')||keys.has('d')?1:0)-(keys.has('arrowleft')||keys.has('a')?1:0),dy=(keys.has('arrowdown')||keys.has('s')?1:0)-(keys.has('arrowup')||keys.has('w')?1:0);if(dx&&dy){dx/=Math.SQRT2;dy/=Math.SQRT2;}move(dx,dy,dt);}if(Date.now()>mongle.until){const tx=player.x+45,ty=Math.min(550,player.y+28),dx=tx-mongle.x,dy=ty-mongle.y,d=Math.hypot(dx,dy);mongle.row=0;if(d>55&&posture==='stand'&&!$('#panel').open&&!lifeDialog.open&&!roomEditing&&lifePage==='room'){const step=Math.min(d-45,dt*175),nx=Math.max(85,Math.min(870,mongle.x+dx/d*step)),ny=Math.max(200,Math.min(560,mongle.y+dy/d*step));if(!blocked(nx,mongle.y))mongle.x=nx;if(!blocked(mongle.x,ny))mongle.y=ny;mongle.row=dx>=0?1:2;}}window.lifeRoomActors?.begin();drawRoom(t);window.lifeRoomActors?.end(t);requestAnimationFrame(frame);}
canvas.addEventListener('keydown',e=>{const k=e.key.toLowerCase();if(['arrowup','arrowdown','arrowleft','arrowright','w','a','s','d'].includes(k)){e.preventDefault();if(posture!=='stand')standUp();keys.add(k);}if(['e','enter'].includes(k)){e.preventDefault();const o=getNearest();if(o)openPanel(o.id);}});window.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));window.addEventListener('blur',()=>keys.clear());canvas.addEventListener('blur',()=>keys.clear());
function hit(e){const r=canvas.getBoundingClientRect(),x=(e.clientX-r.left)*960/r.width,y=(e.clientY-r.top)*650/r.height,list=roomPrefs.activeSpace==='dream'?dreamObjects:objects;return list.find(o=>x>=o.x&&x<=o.x+o.w&&y>=o.y&&y<=o.y+o.h);}
canvas.addEventListener('pointermove',e=>hover=hit(e)?.id||null);canvas.addEventListener('pointerleave',()=>hover=null);canvas.addEventListener('click',e=>{const r=canvas.getBoundingClientRect(),px=(e.clientX-r.left)*960/r.width,py=(e.clientY-r.top)*650/r.height;if(roomPrefs.activeSpace!=='dream'&&Math.hypot(px-mongle.x,py-(mongle.y-10))<30){patMongle();return;}if(roomPrefs.activeSpace!=='dream'&&Math.hypot(px-110,py-490)<45){$('#water').click();return;}const o=hit(e);if(o)openPanel(o.id);else canvas.focus();});
document.querySelectorAll('[data-move]').forEach(b=>{const map={left:'arrowleft',right:'arrowright',up:'arrowup',down:'arrowdown'};b.onpointerdown=e=>{e.preventDefault();keys.add(map[b.dataset.move]);b.setPointerCapture(e.pointerId);};b.onpointerup=b.onpointercancel=()=>keys.clear();});
