// Authenticated records are stored in Supabase; IndexedDB is kept only for one-time migration.
const LIFE_VERSION=1, LIFE_DB='my-life-hq-stories';
const lifeCategories={home:['나라는 집','취향과 기억이 머무는 곳','⌂'],writing:['글쓰기 책상','쓰고 싶은 말들을 천천히','✍'],inspiration:['영감 노트','흘려보내기 아쉬운 한 문장','✧'],journey:['나의 여정','지금의 나를 만든 시간들','🧵'],travel:['가본 곳','장소마다 남겨 둔 나','🗺'],childhood:['어릴 때의 나','작았던 나를 다정하게 만나기','📷'],growth:['성장의 정원','아주 작은 변화도 자라는 곳','🌱'],favorites:['좋아하는 것','나를 설명하는 작은 취향들','♡'],choco:['반려동물의 자리','함께한 기억을 간직하는 곳','💛'],family:['가족 거실','각자의 기억을 함께 펼치는 곳','🏡'],decorate:['집 꾸미기','내가 살고 싶은 공간으로','🎨']};
let lifePage='home',lifeRecords=[],lifeFilter='',lifeDraftTimer,lifeEditing=null,lifeEditorPhoto='',lifeEditorDirty=false;
let lifeMeta;try{lifeMeta=JSON.parse(localStorage.getItem('life-homes-v1'));}catch{}
if(!lifeMeta||!Array.isArray(lifeMeta.homes)||!lifeMeta.homes.length)lifeMeta={active:'original',homes:[{id:'original',name:'나의 집'}]};
let lifeHome=lifeMeta.homes.find(h=>h.id===lifeMeta.active)||lifeMeta.homes[0];
// PRIVATE_DRAFT_KEYS_V1: never adopt unowned device drafts automatically.
const lifeKey=k=>{
 if(/draft|^diary-(code|server|auto)$/.test(k)){
  const user=window.lifeCloud?.userId;
  if(!user)throw new Error('개인 임시 기록은 로그인 후에만 열 수 있어요.');
  return `life-private-v1:${encodeURIComponent(user)}:${encodeURIComponent(lifeHome.id)}:${k}`;
 }
 return `life-${lifeHome.id}-${k}`;
};
let roomPrefs;try{roomPrefs=JSON.parse(localStorage.getItem(lifeKey('room')));}catch{}
roomPrefs={theme:'sage',name:lifeHome.name,layout:{},hair:'#674d3d',outfit:'#bb8a79',...roomPrefs};
const lifeThemes={sage:{name:'햇살 머금은 세이지',wall:'#d6d6b7',floor:'#e1ca9e',sofa:'#8e9f76'},rose:{name:'포근한 로즈',wall:'#e7cccb',floor:'#e6d6bd',sofa:'#b79196'},sky:{name:'맑은 하늘',wall:'#cddde1',floor:'#ded1b8',sofa:'#8babb3'},cream:{name:'따뜻한 크림',wall:'#e8dfc8',floor:'#d9b995',sofa:'#b8a78a'}};
const lifeDB=new Promise((resolve,reject)=>{const r=indexedDB.open(LIFE_DB,1);r.onupgradeneeded=()=>r.result.createObjectStore('records',{keyPath:'id'});r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});
async function lifeLocalAll(){const db=await lifeDB;return new Promise((resolve,reject)=>{const tx=db.transaction('records');const r=tx.objectStore('records').getAll();r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}
async function lifeAll(){return window.lifeCloud.listRecords();}
async function lifePut(record){return window.lifeCloud.putRecord(record);}
async function lifeDelete(id){return window.lifeCloud.deleteRecord(id);}
function lifeText(s){return esc(String(s||''));}
function lifeID(){return crypto.randomUUID?crypto.randomUUID():Date.now()+'-'+Math.random().toString(36).slice(2);}
function lifeDate(){return new Date().toLocaleDateString('sv-SE');}
function lifeSaveMeta(){localStorage.setItem('life-homes-v1',JSON.stringify(lifeMeta));if(cloudReadyForWrites)window.lifeCloud.setSetting('homes',lifeMeta).catch(()=>toast('집 설정을 서버에 저장하지 못했어요.'));}
function lifeRoomSave(){localStorage.setItem(lifeKey('room'),JSON.stringify(roomPrefs));if(cloudReadyForWrites)window.lifeCloud.setSetting(lifeKey('room'),roomPrefs).catch(()=>toast('방 설정을 서버에 저장하지 못했어요.'));}
async function lifeRefresh(){lifeRecords=(await lifeAll()).filter(r=>r.home===lifeHome.id&&!r.deleted);}
const lifeNav=document.createElement('nav');lifeNav.className='life-nav';lifeNav.setAttribute('aria-label','나의 집 공간');document.querySelector('header').after(lifeNav);
const lifeShell=document.createElement('section');lifeShell.className='life-shell';lifeShell.id='life-shell';lifeShell.hidden=true;document.querySelector('main').after(lifeShell);
const lifeDialog=document.createElement('dialog');lifeDialog.id='life-dialog';lifeDialog.innerHTML='<button class="close" aria-label="기록 창 닫기">×</button><div id="life-content"></div>';document.body.append(lifeDialog);
lifeDialog.querySelector('.close').onclick=()=>{if(lifeEditorDirty)lifeKeepDraft();lifeDialog.close();};window.addEventListener('pagehide',()=>{if(lifeEditorDirty)lifeKeepDraft();});lifeDialog.addEventListener('cancel',()=>{if(lifeEditorDirty)lifeKeepDraft();});
const homeButton=document.createElement('button');homeButton.className='life-profile';homeButton.id='life-profile';homeButton.textContent='⌂ '+lifeHome.name;homeButton.onclick=lifeProfiles;document.querySelector('.header-right').prepend(homeButton);
function lifeMenu(){lifeNav.innerHTML='<button data-life="room" class="'+(lifePage==='room'?'active':'')+'">⌂ 내 방</button>'+['home','diary','writing','journey','choco','family','decorate'].map(k=>`<button data-life="${k}" class="${lifePage===k?'active':''}">${lifeCategories[k][2]} ${lifeCategories[k][0]}</button>`).join('');lifeNav.querySelectorAll('button').forEach(b=>b.onclick=()=>lifeGo(b.dataset.life));}
async function lifeGo(page){const stayingInRoom=page==='room'&&lifePage==='room';lifePage=page;document.body.classList.toggle('room-page',page==='room');lifeMenu();$('#panel').close();keys.clear();await lifeRefresh();document.querySelector('main').hidden=page!=='room';lifeShell.hidden=page==='room';if(page!=='room')lifeRender();if(!stayingInRoom)window.scrollTo({top:0,behavior:page==='room'?'auto':'smooth'});}
function lifeHeader(k){const c=lifeCategories[k];return `<div class="life-heading"><div><div class="eyebrow">A HOME MADE OF YOU</div><h1>${c[2]} ${c[0]}</h1><p>${c[1]}</p></div>${!['home','family','decorate'].includes(k)?'<button class="primary" id="life-add">＋ 기록 남기기</button>':''}</div>`;}
function lifeHomeRender(){return lifeHeader('home')+`<div class="life-note">이 집은 <b>${lifeText(lifeHome.name)}</b>의 이야기로 채워져요. 기록과 사진은 로그인한 나의 서버 공간에 저장됩니다. 가족에게 보낼 기록은 직접 골라 앨범 파일로 나눌 수 있어요.</div><div class="life-grid">`+Object.entries(lifeCategories).filter(([k])=>!['home','decorate','growth','study'].includes(k)).map(([k,v])=>`<button class="life-tile" data-goto="${k}"><span class="symbol">${v[2]}</span><strong>${v[0]}</strong><p>${v[1]}</p><span class="life-count">${lifeRecords.filter(r=>r.kind===k).length}개의 이야기</span></button>`).join('')+'</div>';
}
function lifeCard(r){return `<article class="memory-card ${r.kind==='writing'?'shelf':''}">${r.photo?`<img src="${lifeText(r.photo)}" alt="${lifeText(r.title)}의 사진" loading="lazy">`:''}<div class="memory-meta"><span>${lifeText(r.when||'날짜를 몰라도 괜찮아요')}</span><span>${r.share?'가족 앨범에 담기':'나만 간직하기'}</span>${r.place?'<span>⌖ '+lifeText(r.place)+'</span>':''}</div><h3>${lifeText(r.title)}</h3><div class="excerpt">${lifeText((r.body||'').slice(0,170))}${r.body?.length>170?'…':''}</div><button class="ghost" data-read="${lifeText(r.id)}">펼쳐 보기</button></article>`;}
function lifeRender(){
 if(lifePage==='diary'){diaryRender();return;}if(lifePage==='home'){lifeShell.innerHTML=lifeHomeRender();lifeBind();return;}
 if(lifePage==='decorate'){lifeDecorate();return;}if(lifePage==='family'){lifeFamily();return;}
 const k=lifePage;let rows=lifeRecords.filter(r=>k==='writing'?['writing','inspiration'].includes(r.kind):r.kind===k);const needle=lifeFilter.toLowerCase();if(needle)rows=rows.filter(r=>[r.title,r.body,r.place,r.people,r.tags].join(' ').toLowerCase().includes(needle));rows.sort((a,b)=>(b.when||b.created).localeCompare(a.when||a.created,'ko'));
 let extra='';if(k==='writing')extra='<div class="life-note">자유롭게 쓴 글과 떠오른 영감을 함께 모아요. 예전에 영감 노트에 쓴 기록도 여기서 볼 수 있어요.</div>';
 if(k==='inspiration')extra='<div class="life-note">떠오른 한 문장을 적어 두세요. 기존에 쓴 글도 복사해 옮길 수 있어요. 현재 다른 앱과의 자동 연동은 하지 않습니다.</div>';
 if(k==='childhood')extra='<div class="life-note">사진만 남겨도 좋아요. 종이 일기는 사진으로 보관하고, 기억나는 나이와 가족의 이야기를 함께 적어 보세요.</div>';
 if(k==='choco')extra=`<div class="choco-hero"><div class="symbol">💛</div><div><div class="eyebrow">ALWAYS WITH YOU</div><h2>함께한 반려동물에게</h2><blockquote>소중했던 순간과 하고 싶은 말을<br>나만의 기록으로 남겨 보세요.</blockquote><p>사진과 영상 링크, 애칭과 함께한 순간을 천천히 모아두는 자리예요.</p><button class="ghost" id="choco-letter">편지 쓰기</button></div></div>`;
 if(k==='growth')extra='<div class="growth-bed">'+(rows.length?rows.map((r,i)=>`<div class="growth-flower">${['🌱','🌷','🌼','🌻'][i%4]}<span>${lifeText(r.title)}</span></div>`).join(''):'<p>처음 배운 것, 해낸 것, 견뎌낸 시간을 심어 보세요.</p>')+'</div>';
 if(k==='travel')extra=lifeMap(rows);
 lifeShell.innerHTML=lifeHeader(k)+extra+'<div class="life-toolbar"><input id="life-search" aria-label="기록 검색" placeholder="제목, 장소, 함께한 사람 검색" value="'+lifeText(lifeFilter)+'"><span class="life-count">'+rows.length+'개의 이야기</span></div><div class="'+(k==='journey'?'life-timeline':'life-grid')+'" id="life-results">'+(rows.map(lifeCard).join('')||'<div class="empty-state">아직 빈 페이지예요.<br>짧은 문장 하나, 사진 한 장부터 남겨 보세요.</div>')+'</div>';
 lifeBind();$('#life-add').onclick=()=>lifeEdit(null,k);if($('#choco-letter'))$('#choco-letter').onclick=()=>lifeEdit(null,'choco','함께한 반려동물에게');$('#life-search').oninput=e=>{lifeFilter=e.target.value;const pos=e.target.selectionStart;lifeRender();$('#life-search').focus();$('#life-search').setSelectionRange(pos,pos);};
}
function lifeBind(){lifeShell.querySelectorAll('[data-goto]').forEach(b=>b.onclick=()=>{lifeFilter='';lifeGo(b.dataset.goto);});lifeShell.querySelectorAll('[data-read]').forEach(b=>b.onclick=()=>lifeRead(b.dataset.read));}
function lifeMap(rows){const located=rows.filter(r=>Number.isFinite(r.lat)&&Number.isFinite(r.lon));return '<div class="map-preview"><svg viewBox="0 0 720 320" role="img" aria-label="가본 곳의 위도와 경도 지도"><rect width="720" height="320" fill="#e3ede2"/>'+Array.from({length:13},(_,i)=>`<path d="M${i*60} 0V320" stroke="#c9d8c6" fill="none"/>`).join('')+Array.from({length:7},(_,i)=>`<path d="M0 ${i*53.3}H720" stroke="#c9d8c6" fill="none"/>`).join('')+'<text x="12" y="22" fill="#7c9173" font-size="12">90° N</text><text x="12" y="309" fill="#7c9173" font-size="12">90° S</text>'+located.map(r=>`<g><circle cx="${(r.lon+180)*2}" cy="${(90-r.lat)*320/180}" r="6" fill="#a2765e"/><text x="${Math.max(12,Math.min(610,(r.lon+180)*2+9))}" y="${Math.max(35,(90-r.lat)*320/180)}" fill="#566c4f" font-size="12">${lifeText(r.place||r.title)}</text></g>`).join('')+'</svg><p>위·경도를 넣은 장소가 좌표 지도에 표시돼요. 장소 이름만 적어도 여행 기록을 남길 수 있고, 상세 화면에서 실제 지도를 열 수 있어요.</p></div>';}
function lifeShow(html){$('#life-content').innerHTML=html;if(!lifeDialog.open)lifeDialog.showModal();keys.clear();}
function lifeRead(id){const r=lifeRecords.find(r=>r.id===id);if(!r)return;if(r.kind==='diary'){diaryRead(id);return;}lifeEditorDirty=false;lifeEditing=null;lifeShow(`<div class="eyebrow">${lifeText(lifeCategories[r.kind]?.[0]||'가족의 기억')}</div><h2>${lifeText(r.title)}</h2><p>${lifeText([r.when,r.place,r.people].filter(Boolean).join(' · '))}</p>${r.photo?`<img class="life-photo" src="${lifeText(r.photo)}" alt="${lifeText(r.title)}">`:''}<div class="life-reading">${lifeText(r.body)}</div>${r.url?linkButton(r.url,'연결된 글 / 영상 열기'):''}${r.place?linkButton('https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(r.place),'이 장소 지도 열기'):''}<p>${r.share?'가족 앨범 내보내기에 포함되는 기록입니다.':'개인 기록입니다. 가족 앨범에 포함되지 않습니다.'}</p><div class="actions"><button class="primary" id="life-edit">기록 수정</button><button class="ghost danger" id="life-delete">휴지통으로</button></div><h3>이 기억에 보태는 이야기</h3><div id="life-comments">${(r.comments||[]).map(c=>`<div class="family-bubble"><b>${lifeText(c.name)}</b><br>${lifeText(c.body)}</div>`).join('')}</div><form id="comment-form" class="life-form"><label class="field full">이름<input name="name" required maxlength="60" placeholder="이야기를 남기는 사람"></label><label class="field full">기억 한 조각<textarea name="body" required maxlength="10000" placeholder="내가 기억하는 그날은…"></textarea></label><button class="ghost">이야기 보태기</button><p class="full">내 서버 공간에 저장됩니다. 가족에게 보태진 이야기를 보내려면 가족 앨범을 다시 내보내세요.</p></form>`);
 $('#life-edit').onclick=()=>lifeEdit(r);$('#life-delete').onclick=async()=>{await lifePut({...r,deleted:true,updated:new Date().toISOString()});lifeDialog.close();await lifeRefresh();lifeRender();toast('휴지통으로 옮겼어요. 가족 거실에서 복원할 수 있어요.');};$('#comment-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);try{await lifePut({...r,comments:[...(r.comments||[]),{id:lifeID(),name:String(f.get('name')).trim(),body:String(f.get('body')).trim(),date:lifeDate()}],updated:new Date().toISOString()});await lifeRefresh();lifeRead(id);}catch{toast('저장하지 못했어요. 내용을 복사해 보관해 주세요.');}};
}
function lifeKeepDraft(){if(!lifeEditing)return;try{const form=$('#story-form');if(form){const f=Object.fromEntries(new FormData(form));delete f.photo;localStorage.setItem(lifeKey('draft-'+lifeEditing.kind),JSON.stringify({...f,id:lifeEditing.id,kind:lifeEditing.kind,share:form.elements.share.checked}));$('#draft-status').textContent='작성 중인 글을 임시 보관했어요.';}}catch{if($('#draft-status'))$('#draft-status').textContent='임시 저장 공간이 부족해요. 저장 버튼으로 기록을 남겨 주세요.';}}
function lifeEdit(record,kind,title){if((record?.kind||kind)==='diary'){diaryForm(record?.when||lifeDate());return;}clearTimeout(lifeDraftTimer);kind=record?.kind||kind;let draft=null;if(!record)try{draft=JSON.parse(localStorage.getItem(lifeKey('draft-'+kind)));}catch{}const r=record||draft||{id:lifeID(),kind,title:title||'',when:lifeDate(),body:'',share:false};lifeEditing=r;lifeEditorPhoto=record?.photo||'';lifeEditorDirty=false;
 lifeShow(`<div class="eyebrow">${lifeText(lifeCategories[kind]?.[0])}</div><h2>${record?'기억을 다듬기':'새 페이지 남기기'}</h2><form id="story-form" class="life-form"><label class="field full">제목<input name="title" required maxlength="180" value="${lifeText(r.title)}" placeholder="이 페이지에 이름을 붙여 주세요"></label><label class="field">언제였나요?<input name="when" maxlength="80" value="${lifeText(r.when)}" placeholder="2020년 / 초등학생 때 / 날짜 몰라도 괜찮아요"></label><label class="field">함께한 사람<input name="people" maxlength="200" value="${lifeText(r.people)}" placeholder="나, 반려동물, 우리 가족…"></label><label class="field full">이야기<textarea name="body" maxlength="100000" placeholder="떠오르는 만큼, 내 속도로 적어 보세요.">${lifeText(r.body)}</textarea></label><label class="field">장소<input name="place" maxlength="200" value="${lifeText(r.place)}" placeholder="도시, 동네, 기억나는 장소"></label><label class="field">태그<input name="tags" maxlength="200" value="${lifeText(r.tags)}" placeholder="여행, 가족, 새로운 시작…"></label>${kind==='travel'?`<label class="field">위도 (선택)<input name="lat" type="number" min="-90" max="90" step="any" value="${r.lat??''}"></label><label class="field">경도 (선택)<input name="lon" type="number" min="-180" max="180" step="any" value="${r.lon??''}"></label>`:''}<label class="field full">Notion 글 / 영상 / 음악 주소 (선택)<input name="url" type="url" value="${lifeText(r.url)}" placeholder="https://…"></label><label class="field full">사진 또는 종이 일기 사진 (선택)<input type="file" name="photo" accept="image/jpeg,image/png,image/webp"><small>사진은 줄여서 내 서버 공간에 저장해요. 글만 먼저 남겨도 좋아요.</small></label><div class="full" id="story-photo">${lifeEditorPhoto?'<img src="'+lifeText(lifeEditorPhoto)+'" alt="첨부 사진"><button type="button" class="ghost" id="remove-photo">사진 빼기</button>':''}</div><label class="check-label full"><input type="checkbox" name="share" ${r.share?'checked':''}> 이 기록을 가족 앨범 내보내기에 포함</label><div class="life-note full">체크해도 자동 공개되지 않아요. 가족 거실에서 앨범 파일을 내보낼 때만 포함됩니다.</div><div class="actions full"><button class="primary" id="story-save">기록 저장</button><button type="button" class="ghost" id="draft-save">임시 보관</button></div><div class="save-state full" id="draft-status" role="status">${draft?'작성하던 글을 불러왔어요. 사진은 다시 선택해 주세요.':''}</div></form>`);
 const f=$('#story-form');f.oninput=()=>{lifeEditorDirty=true;clearTimeout(lifeDraftTimer);lifeDraftTimer=setTimeout(lifeKeepDraft,600);};$('#draft-save').onclick=lifeKeepDraft;const remove=()=>{lifeEditorPhoto='';$('#story-photo').replaceChildren();};if($('#remove-photo'))$('#remove-photo').onclick=remove;
 f.elements.photo.onchange=async e=>{const file=e.target.files[0];if(!file)return;$('#story-save').disabled=true;try{lifeEditorPhoto=await lifePhoto(file);$('#story-photo').innerHTML='<img src="'+lifeText(lifeEditorPhoto)+'" alt="선택한 사진"><button type="button" class="ghost" id="remove-photo">사진 빼기</button>';$('#remove-photo').onclick=remove;}catch{$('#draft-status').textContent='사진을 열 수 없어요. JPG, PNG, WebP 사진을 선택해 주세요.';}finally{$('#story-save').disabled=false;}};
 f.onsubmit=async e=>{e.preventDefault();clearTimeout(lifeDraftTimer);const f=e.target,v=Object.fromEntries(new FormData(f));if(v.url&&!safeURL(v.url)){$('#draft-status').textContent='연결 주소는 http 또는 https로 시작해야 해요.';return;}const record={id:r.id,home:lifeHome.id,kind,title:v.title.trim(),body:v.body,when:v.when.trim(),people:v.people.trim(),tags:v.tags.trim(),place:v.place.trim(),url:v.url? safeURL(v.url):'',photo:lifeEditorPhoto,share:f.elements.share.checked,lat:v.lat!==undefined&&v.lat!==''?Number(v.lat):null,lon:v.lon!==undefined&&v.lon!==''?Number(v.lon):null,created:r.created||new Date().toISOString(),updated:new Date().toISOString(),comments:r.comments||[]};if(!record.title){$('#draft-status').textContent='제목을 적어 주세요.';return;}$('#story-save').disabled=true;try{await lifePut(record);lifeEditorDirty=false;localStorage.removeItem(lifeKey('draft-'+kind));lifeEditing=null;lifeDialog.close();await lifeRefresh();lifePage=kind;lifeMenu();lifeShell.hidden=false;document.querySelector('main').hidden=true;lifeRender();toast('이야기를 저장했어요.');}catch{$('#draft-status').textContent='저장하지 못했어요. 기기 저장 공간을 확인해 주세요. 내용은 복사해서 보관해 주세요.';$('#story-save').disabled=false;}};
}
async function lifePhoto(file){if(!/^image\/(jpeg|png|webp)$/.test(file.type))throw Error('type');const bitmap=await createImageBitmap(file);const scale=Math.min(1,1400/Math.max(bitmap.width,bitmap.height));const c=document.createElement('canvas');c.width=Math.round(bitmap.width*scale);c.height=Math.round(bitmap.height*scale);c.getContext('2d').drawImage(bitmap,0,0,c.width,c.height);bitmap.close();return c.toDataURL('image/jpeg',.82);}
function lifeDecorate(){lifeShell.innerHTML=lifeHeader('decorate')+`<form id="room-form"><label class="field">내 집 이름<input name="name" maxlength="60" required value="${lifeText(roomPrefs.name)}"></label><h3>집의 분위기</h3><div class="palette-choice">${Object.entries(lifeThemes).map(([k,v])=>`<label><input type="radio" name="theme" value="${k}" ${roomPrefs.theme===k?'checked':''}> <span style="display:inline-block;width:28px;height:18px;border-radius:5px;background:${v.wall}"></span> ${v.name}</label>`).join('')}</div><div class="life-form"><label class="field">내 캐릭터 머리색<input name="hair" type="color" value="${roomPrefs.hair}"></label><label class="field">내 캐릭터 옷 색<input name="outfit" type="color" value="${roomPrefs.outfit}"></label></div><div class="actions"><button class="primary">꾸미기 저장</button><button type="button" class="ghost" id="layout-edit">가구 배치하기</button><button type="button" class="ghost" id="layout-reset">기본 배치로</button></div></form><div class="life-note" style="margin-top:25px">가구 배치하기를 누르면 방 안에서 문·액자·화분·노트·앨범을 포함한 모든 기능 가구를 끌어서 옮길 수 있어요. 선택 후 방향키로도 조금씩 옮겨요. 배치 완료를 눌러 저장하세요. 다른 사람은 ‘내 집’ 메뉴에서 자기 집을 새로 만들 수 있어요.</div>`;
 $('#room-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);roomPrefs={...roomPrefs,name:String(f.get('name')).trim(),theme:f.get('theme'),hair:f.get('hair'),outfit:f.get('outfit')};lifeHome.name=roomPrefs.name;lifeSaveMeta();lifeRoomSave();homeButton.textContent='⌂ '+lifeHome.name;toast('나만의 집을 저장했어요.');lifeGo('room');};$('#layout-edit').onclick=()=>{roomEditing=true;lifeGo('room');$('#layout-toggle').hidden=false;$('#layout-toggle').textContent='배치 완료 · 저장';toast('가구를 잡고 끌어 보세요.');};$('#layout-reset').onclick=()=>{roomPrefs.layout={};lifeRoomSave();roomApplyLayout();standUp();player.x=465;player.y=390;toast('기본 배치로 돌아왔어요.');};
}
function lifeProfiles(){lifeEditorDirty=false;lifeShow(`<div class="eyebrow">EVERYONE HAS A STORY</div><h2>각자의 작은 집</h2><p>이 브라우저 안에서 사람마다 별도의 집과 기록을 만들 수 있어요. 이 기능은 로그인이나 보안 계정이 아니므로 같은 브라우저를 쓰는 사람끼리 서로 집을 열 수 있습니다.</p><div class="family-list">${lifeMeta.homes.filter(h=>!h.archived).map(h=>`<button class="family-person" data-home="${lifeText(h.id)}">⌂ ${lifeText(h.name)}${h.id===lifeHome.id?' · 지금 여기':''}</button>`).join('')}</div><form id="new-home" class="life-form"><label class="field full">새 집 이름<input name="name" maxlength="60" required placeholder="예: 엄마의 작은 정원"></label><button class="primary">나만의 집 만들기</button></form>`);lifeDialog.querySelectorAll('[data-home]').forEach(b=>b.onclick=()=>lifeSwitch(b.dataset.home));const archive=document.createElement('div');archive.className='actions';for(const h of lifeMeta.homes.filter(h=>h.id!==lifeHome.id)){const b=document.createElement('button');b.className='ghost';b.textContent=(h.archived?'집 다시 꺼내기: ':'집 보관하기: ')+h.name;b.onclick=()=>{h.archived=!h.archived;lifeSaveMeta();lifeProfiles();};archive.append(b);}$('#life-content').append(archive);$('#new-home').onsubmit=e=>{e.preventDefault();const name=new FormData(e.target).get('name').trim();if(!name)return;const h={id:lifeID(),name};lifeMeta.homes.push(h);lifeSaveMeta();lifeSwitch(h.id);};}
function lifeSwitch(id){lifeMeta.active=id;lifeSaveMeta();location.reload();}
function lifeDownload(name,body,type){const url=URL.createObjectURL(new Blob([body],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);}
function lifePortable(rows){const data=JSON.stringify({format:'life-family-album',version:1,home:lifeHome.name,records:rows}).replace(/</g,'\\u003c');return `<!doctype html><html lang="ko"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>함께 펼치는 가족 앨범</title><style>body{max-width:850px;margin:auto;padding:30px 20px;background:#f5f1e8;color:#485141;font:16px system-ui}article{padding:25px;margin:25px 0;background:#fffdf6;border:1px solid #deded0;border-radius:18px}img{max-width:100%;max-height:500px;border-radius:12px}p{white-space:pre-wrap;overflow-wrap:anywhere;line-height:1.9}textarea,input{display:block;box-sizing:border-box;width:100%;padding:12px;margin:10px 0;border:1px solid #cdd6c3;border-radius:8px;font:inherit}button{padding:12px 18px;border:0;border-radius:9px;background:#657a59;color:white;cursor:pointer}.note{font-size:13px;color:#7a826e}a{color:#657a59}</style><h1 id="album-title"></h1><p>가족이 함께 펼치는 기억 앨범</p><p class="note">앨범 파일에 포함된 기록만 볼 수 있어요. 보태 쓴 이야기는 아래에서 파일로 저장해 가족에게 돌려보내 주세요. 자동으로 전송되지는 않습니다.</p><div id="records"></div><button id="export">보탠 이야기 파일로 저장</button><script>const album=${data};const esc=s=>String(s||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));document.getElementById('album-title').textContent=album.home;function render(){document.getElementById('records').innerHTML=album.records.map((r,i)=>'<article><small>'+esc([r.when,r.place].filter(Boolean).join(' · '))+'</small><h2>'+esc(r.title)+'</h2>'+(r.photo?'<img src="'+esc(r.photo)+'" alt="추억 사진">':'')+'<p>'+esc(r.body)+'</p>'+(r.comments||[]).map(c=>'<p><b>'+esc(c.name)+'</b><br>'+esc(c.body)+'</p>').join('')+'<form data-i="'+i+'"><input name="name" placeholder="이름" required maxlength="60"><textarea name="body" placeholder="내가 기억하는 그날은…" required maxlength="10000"></textarea><button>이야기 보태기</button></form></article>').join('');document.querySelectorAll('form').forEach(f=>f.onsubmit=e=>{e.preventDefault();const v=new FormData(f),r=album.records[Number(f.dataset.i)];r.comments=r.comments||[];r.comments.push({id:crypto.randomUUID?crypto.randomUUID():Date.now()+Math.random().toString(),name:v.get('name'),body:v.get('body'),date:new Date().toISOString()});r.updated=new Date().toISOString();render();});}render();document.getElementById('export').onclick=()=>{const u=URL.createObjectURL(new Blob([JSON.stringify(album)],{type:'application/json'}));const a=document.createElement('a');a.href=u;a.download='가족이-보탠-이야기.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),30000);};<\/script></html>`;}
function lifeFamily(){const shared=lifeRecords.filter(r=>r.share&&r.kind!=='diary'),people=[...new Set(lifeRecords.flatMap(r=>(r.people||'').split(/[,，]/)).map(s=>s.trim()).filter(Boolean))];lifeShell.innerHTML=lifeHeader('family')+`<div class="life-note"><b>현재는 파일로 나누는 가족 앨범이에요.</b><br>가족용으로 고른 기록 ${shared.length}개만 담아 HTML 앨범을 만들 수 있어요. 가족은 파일을 열어 읽고, 기억을 덧붙인 파일을 돌려줄 수 있습니다. 인터넷 초대 링크·로그인·실시간 공동 편집은 아직 연결되지 않았어요.</div><div class="actions"><button class="primary" id="family-export">가족에게 보낼 앨범 만들기 (${shared.length}개)</button><button class="ghost" id="life-backup">내 기록 전체 백업</button><label class="ghost" style="cursor:pointer">앨범 / 백업 가져오기<input hidden id="life-import" type="file" accept="application/json,.json"></label><button class="ghost" id="life-trash">휴지통</button></div><p class="app-status">전체 백업에는 비공개 기록도 포함됩니다. 가족에게는 ‘가족 앨범’을 보내 주세요.</p><h3>기억 속 함께한 사람들</h3><div class="family-list">${people.map(n=>'<div class="family-person">♡ '+lifeText(n)+'</div>').join('')||'<p>기록에 함께한 사람을 적으면 이곳에 모여요.</p>'}</div><div class="life-grid">${shared.map(lifeCard).join('')||'<div class="empty-state">기록을 쓸 때 ‘가족 앨범에 포함’을 골라 주세요.<br>개인 기록은 이곳에 나오지 않아요.</div>'}</div>`;lifeBind();$('#family-export').onclick=()=>{if(!shared.length){toast('먼저 가족과 나눌 기록을 골라 주세요.');return;}lifeDownload('우리-가족-추억-앨범.html',lifePortable(shared),'text/html;charset=utf-8');toast('가족 앨범을 파일로 만들었어요. 원하는 가족에게 직접 보내 주세요.');};$('#life-backup').onclick=async()=>{const rows=(await lifeAll()).filter(r=>r.home===lifeHome.id);lifeDownload('나의-집-전체백업-'+lifeDate()+'.json',JSON.stringify({format:'life-home-backup',version:1,home:lifeHome.name,room:roomPrefs,daily:state,records:rows}), 'application/json');};$('#life-import').onchange=lifeImport;$('#life-trash').onclick=lifeTrash;}
function lifeValidateImport(data){if(!['life-family-album','life-home-backup'].includes(data?.format)||data.version!==1||!Array.isArray(data.records)||data.records.length>3000)throw Error('형식을 읽을 수 없어요. 이 집에서 만든 JSON 파일을 골라 주세요.');return data.records.map(r=>{if(!r||(typeof r.id!=='string'||!/^[-A-Za-z0-9_:.,]{1,120}$/.test(r.id))||!lifeCategories[r.kind]||['home','family','decorate'].includes(r.kind)||typeof r.title!=='string'||typeof r.body!=='string'||r.body.length>100000||r.title.length>180)throw Error('기록 형식이 올바르지 않아요.');const str=(v,n)=>typeof v==='string'?v.slice(0,n):'';return {id:r.id.slice(0,120),home:lifeHome.id,kind:r.kind,title:r.title,body:r.body,when:str(r.when,80),people:str(r.people,200),tags:str(r.tags,200),place:str(r.place,200),url:safeURL(r.url)||'',photo:typeof r.photo==='string'&&/^data:image\/(jpeg|png|webp);base64,[A-Za-z0-9+/=]+$/.test(r.photo)&&r.photo.length<5000000?r.photo:'',diary:r.kind==='diary'&&r.diary?{mood:['편안','기쁨','뿌듯','복잡','지침','슬픔'].includes(r.diary.mood)?r.diary.mood:'',events:str(r.diary.events,25000),thoughts:str(r.diary.thoughts,25000),gratitude:str(r.diary.gratitude,25000),tomorrow:str(r.diary.tomorrow,25000)}:undefined,notion:r.kind==='diary'&&r.notion&&safeURL(r.notion.url)?{url:safeURL(r.notion.url),changed:!!r.notion.changed}:undefined,share:r.kind==='diary'?false:!!r.share,deleted:!!r.deleted,lat:typeof r.lat==='number'&&Math.abs(r.lat)<=90?r.lat:null,lon:typeof r.lon==='number'&&Math.abs(r.lon)<=180?r.lon:null,created:str(r.created,50)||new Date().toISOString(),updated:str(r.updated,50)||new Date().toISOString(),comments:(Array.isArray(r.comments)?r.comments:[]).slice(0,500).map(c=>({id:str(c.id,120)||lifeID(),name:str(c.name,60),body:str(c.body,10000),date:str(c.date,50)}))};});}
async function lifeImport(e){const file=e.target.files[0];if(!file)return;if(file.size>30000000){toast('파일이 너무 커요. 30MB 이하 파일을 골라 주세요.');return;}try{const parsed=JSON.parse(await file.text()),incoming=lifeValidateImport(parsed);lifeShow(`<h2>가져올 기록을 확인해 주세요</h2><p>${lifeText(parsed.home)}의 ${incoming.length}개 기록이에요. 기존 기록은 덮어쓰지 않고, 새 기록과 가족이 보탠 이야기만 합칩니다.</p><p>같은 제목의 새 기록도 별도 페이지로 남을 수 있어요.</p><label class="check-label"><input type="checkbox" id="restore-room"> 전체 백업의 집 꾸미기도 함께 복원</label><button class="primary" id="import-confirm">내 집에 가져오기</button><p id="import-status" role="status"></p>`);$('#import-confirm').onclick=async()=>{const button=$('#import-confirm');button.disabled=true;try{const all=await lifeAll();for(const r of incoming){const existing=all.find(x=>(x.id===r.id||x.id===lifeHome.id+'-'+r.id)&&x.home===lifeHome.id);if(existing){const comments=[...(existing.comments||[])];for(const c of r.comments)if(!comments.some(x=>x.id===c.id))comments.push(c);await lifePut({...existing,comments});}else{const collision=all.some(x=>x.id===r.id);await lifePut({...r,id:collision?lifeHome.id+'-'+r.id:r.id});}}if($('#restore-room').checked&&parsed.format==='life-home-backup'&&parsed.room){const prefs=parsed.room;roomPrefs={...roomPrefs,theme:lifeThemes[prefs.theme]?prefs.theme:roomPrefs.theme,hair:/^#[0-9a-f]{6}$/i.test(prefs.hair)?prefs.hair:roomPrefs.hair,outfit:/^#[0-9a-f]{6}$/i.test(prefs.outfit)?prefs.outfit:roomPrefs.outfit};const layout={};if(parsed.daily&&Array.isArray(parsed.daily.tasks)&&parsed.daily.tasks.length===3){state.tasks=parsed.daily.tasks.map(t=>({text:String(t.text||'').slice(0,160),done:!!t.done}));state.day=String(parsed.daily.day||'');state.notes=String(parsed.daily.notes||'').slice(0,100000);for(const k of Object.keys(state.links))state.links[k]=safeURL(parsed.daily.links?.[k])||'';save();rollover();renderTasks();}for(const b of roomBase){const pos=prefs.layout?.[b.id];if(pos&&Number.isFinite(pos.x)&&Number.isFinite(pos.y))layout[b.id]={x:Math.max(78-b.x,Math.min(875-b.x-b.w,pos.x)),y:Math.max(85-b.y,Math.min(545-b.y-b.h,pos.y))};}roomPrefs.layout=layout;lifeRoomSave();roomApplyLayout();}lifeDialog.close();await lifeRefresh();lifeFamily();toast('기록과 보태진 이야기를 가져왔어요.');}catch{$('#import-status').textContent='가져오기를 마치지 못했어요. 원본 파일은 그대로 두고 저장 공간을 확인해 주세요.';button.disabled=false;}};}catch(error){toast(error.message||'파일을 읽을 수 없어요.');}}
async function lifeTrash(){const rows=(await lifeAll()).filter(r=>r.home===lifeHome.id&&r.deleted);lifeShow('<h2>잠시 치워 둔 이야기</h2><p>실수로 옮겼다면 언제든 다시 꺼낼 수 있어요.</p>'+rows.map(r=>`<div class="family-bubble">${lifeText(r.title)} <button class="ghost" data-restore="${lifeText(r.id)}">복원</button></div>`).join('')+(rows.length?'':'<p>휴지통이 비어 있어요.</p>'));lifeDialog.querySelectorAll('[data-restore]').forEach(b=>b.onclick=async()=>{const r=rows.find(x=>x.id===b.dataset.restore);await lifePut({...r,deleted:false});await lifeRefresh();await lifeTrash();lifeFamily();});}
let roomEditing=false,roomDrag=null,roomDragged=false;const roomBase=objects.map(o=>({...o}));
function roomApplyLayout(){for(const o of objects){const base=roomBase.find(b=>b.id===o.id),offset=roomPrefs.layout[o.id]||{x:0,y:0};o.x=base.x+offset.x;o.y=base.y+offset.y;}}
function roomTransform(id){const pos=roomPrefs.layout[id]||{x:0,y:0};ctx.save();ctx.translate(pos.x,pos.y);}
const layoutButton=document.createElement('button');layoutButton.className='ghost';layoutButton.id='layout-toggle';layoutButton.textContent='배치 완료 · 저장';layoutButton.hidden=true;document.querySelector('[aria-label="방 안 행동"]').append(layoutButton);layoutButton.onclick=()=>{roomEditing=false;layoutButton.hidden=true;lifeRoomSave();player.x=465;player.y=390;if(blocked(player.x,player.y)){player.x=90;player.y=560;}toast('가구 배치를 저장했어요.');};
canvas.addEventListener('pointerdown',e=>{if(!roomEditing)return;const r=canvas.getBoundingClientRect(),px=(e.clientX-r.left)*960/r.width,py=(e.clientY-r.top)*650/r.height;const o=objects.find(o=>px>=o.x&&px<=o.x+o.w&&py>=o.y&&py<=o.y+o.h);if(o){roomDrag={id:o.id,x:px,y:py,base:roomPrefs.layout[o.id]||{x:0,y:0}};roomDragged=false;canvas.setPointerCapture(e.pointerId);}});
canvas.addEventListener('pointermove',e=>{if(!roomEditing||!roomDrag)return;const r=canvas.getBoundingClientRect(),px=(e.clientX-r.left)*960/r.width,py=(e.clientY-r.top)*650/r.height,b=roomBase.find(o=>o.id===roomDrag.id);let x=Math.round((roomDrag.base.x+px-roomDrag.x)/10)*10,y=Math.round((roomDrag.base.y+py-roomDrag.y)/10)*10;x=Math.max(78-b.x,Math.min(875-b.x-b.w,x));y=Math.max(85-b.y,Math.min(545-b.y-b.h,y));roomPrefs.layout[b.id]={x,y};roomApplyLayout();roomDragged=true;});canvas.addEventListener('pointerup',()=>{roomDrag=null;});canvas.addEventListener('click',e=>{if(roomEditing||roomDragged){e.stopImmediatePropagation();roomDragged=false;}},true);
function drawLifeObjects(t){const rounded=(x,y,w,h,r,color)=>{ctx.fillStyle=color;ctx.beginPath();ctx.roundRect(x,y,w,h,r);ctx.fill();};roomTransform('memory');rounded(252,103,50,47,5,'#a7886b');rounded(257,108,40,37,3,'#f0e3cf');label('♡',277,134);label('쪼꼬',277,164);ctx.restore();roomTransform('focus');roomTransform('story');rect(111,313,53,27,'#f6ecd0');rect(136,313,2,27,'#c8b798');for(let i=0;i<3;i++){rect(116,320+i*5,14,1,'#b6ad90');rect(143,320+i*5,14,1,'#b6ad90');}ctx.font='bold 9px Pretendard, sans-serif';ctx.fillStyle='#5b654e';ctx.textAlign='center';ctx.fillText('JOURNAL',137,351);ctx.restore();ctx.restore();const count=lifeRecords.filter(r=>r.kind==='growth').length;for(let i=0;i<Math.min(count,8);i++){const x=280+i*19;rect(x,548,2,12,'#7c945c');ctx.fillStyle=['#dba6a1','#e3c984','#c6b0cb'][i%3];ctx.beginPath();ctx.arc(x+1,546,4,0,Math.PI*2);ctx.fill();}if(roomEditing){ctx.fillStyle='#faf4dd';ctx.fillRect(320,594,320,26);label('가구를 끌어서 옮겨 보세요',480,612);}}
canvas.addEventListener('click',e=>{if(roomEditing)return;const r=canvas.getBoundingClientRect(),x=(e.clientX-r.left)*960/r.width,y=(e.clientY-r.top)*650/r.height;if(x>=250&&x<=306&&y>=100&&y<=151){e.stopImmediatePropagation();lifeGo('choco');}else if(x>=450&&x<=523&&y>=482&&y<=535){e.stopImmediatePropagation();lifeGo('journey');}},true);
async function lifeInit(){try{await window.lifeCloud.ready;const [remoteHomes,remoteRoom,remoteDaily]=await Promise.all([window.lifeCloud.getSetting('homes'),window.lifeCloud.getSetting(lifeKey('room')),window.lifeCloud.getSetting('daily')]);if(remoteHomes?.homes?.length){lifeMeta=remoteHomes;lifeHome=lifeMeta.homes.find(h=>h.id===lifeMeta.active)||lifeMeta.homes[0];localStorage.setItem('life-homes-v1',JSON.stringify(lifeMeta));}if(remoteRoom){roomPrefs={...roomPrefs,...remoteRoom};localStorage.setItem(lifeKey('room'),JSON.stringify(roomPrefs));}window.__legacyServerDaily=remoteDaily?JSON.parse(JSON.stringify(remoteDaily)):null;window.__legacyServerDaily=remoteDaily?JSON.parse(JSON.stringify(remoteDaily)):null;window.__legacyServerDaily=remoteDaily?JSON.parse(JSON.stringify(remoteDaily)):null;window.__legacyServerDaily=remoteDaily?JSON.parse(JSON.stringify(remoteDaily)):null;if(remoteDaily?.tasks?.length===3){state={...state,...remoteDaily,links:{...state.links,...remoteDaily.links}};localStorage.setItem(STORE,JSON.stringify(state));rollover();renderTasks();}const planChanged=applyTodayStudyPlan();cloudReadyForWrites=true;await Promise.all([remoteHomes?Promise.resolve():window.lifeCloud.setSetting('homes',lifeMeta),remoteRoom?Promise.resolve():window.lifeCloud.setSetting(lifeKey('room'),roomPrefs),planChanged||!remoteDaily?window.lifeCloud.setSetting('daily',state):Promise.resolve()]);await lifeRefresh();if(await window.lifeCloud.countRecords()===0){const local=await lifeLocalAll();if(local.length&&confirm('이 기기에만 있던 기존 기록을 안전한 서버 저장소로 옮길까요?')){for(const record of local)await lifePut(record);await lifeRefresh();toast('기존 기록을 서버로 옮겼어요.');}}roomApplyLayout();lifePage='room';document.body.classList.add('room-page');lifeMenu();homeButton.textContent='⌂ '+lifeHome.name;document.querySelector('h1').textContent=roomPrefs.name+'에서, 내 속도로.';window.roomSpaceButtons?.();}catch(error){console.error(error);toast('서버 저장소를 열지 못했어요. Supabase 연결과 권한 설정을 확인해 주세요.');}}
window.lifeAppReady=lifeInit();

let installRequest=null;const installButton=document.createElement('button');installButton.className='ghost';installButton.hidden=true;installButton.textContent='집을 앱으로 설치';document.querySelector('.header-right').append(installButton);window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installRequest=e;installButton.hidden=false;});installButton.onclick=async()=>{if(installRequest){await installRequest.prompt();installRequest=null;installButton.hidden=true;}};

lifeCategories.diary=['나의 일기장','오늘을 적고, 내 마음을 정리하는 시간','📓'];
const diaryMoods={'편안':'🌿','기쁨':'☀️','뿌듯':'🌷','복잡':'☁️','지침':'🌙','슬픔':'🌧️'};
let diaryMonth=lifeDate().slice(0,7),diaryQuery='',diaryMood='',diaryDate=lifeDate(),diaryDraftTimer,diaryPhoto='',diaryWriting=false;
function diaryRows(){return lifeRecords.filter(r=>r.kind==='diary');}
function diaryFind(date){return diaryRows().find(r=>r.when===date);}
function diaryDraftKey(date){return lifeKey('diary-draft-'+date);}
function diaryBody(d){return [['오늘 있었던 일',d.events],['내 마음과 생각',d.thoughts],['고마웠던 것',d.gratitude],['내일의 나에게',d.tomorrow]].filter(([,v])=>v?.trim()).map(([k,v])=>'## '+k+'\n'+v.trim()).join('\n\n');}
function diaryMarkdown(r){return '# '+r.title+'\n\n날짜: '+r.when+'\n기분: '+(r.diary?.mood||'아직 고르지 않음')+'\n분류: 개인 · 일기\n\n'+r.body;}
function diaryRender(){
 diaryWriting=false;let rows=diaryRows().filter(r=>r.when.startsWith(diaryMonth));if(diaryQuery)rows=rows.filter(r=>(r.title+' '+r.body).toLowerCase().includes(diaryQuery.toLowerCase()));if(diaryMood)rows=rows.filter(r=>r.diary?.mood===diaryMood);rows.sort((a,b)=>b.when.localeCompare(a.when));
 const monthRows=diaryRows().filter(r=>r.when.startsWith(diaryMonth)),[year,month]=diaryMonth.split('-').map(Number),first=new Date(year,month-1,1).getDay(),days=new Date(year,month,0).getDate();
 const moodCounts={};monthRows.forEach(r=>{if(r.diary?.mood)moodCounts[r.diary.mood]=(moodCounts[r.diary.mood]||0)+1;});const moodTop=Object.entries(moodCounts).sort((a,b)=>b[1]-a[1])[0];
 lifeShell.innerHTML=`<div class="life-heading"><div><div class="eyebrow">A PAGE FOR TODAY</div><h1>📓 나의 일기장</h1><p>길게 쓰지 않아도 괜찮아. 오늘의 나를 조금 남겨두자.</p></div><button class="primary" id="diary-today">오늘 일기 쓰기</button></div><div class="diary-summary"><div><strong>${monthRows.length}</strong><span>이번 달 남긴 하루</span></div><div><strong>${moodTop?diaryMoods[moodTop[0]]:'✧'}</strong><span>${moodTop?lifeText(moodTop[0])+'한 날 '+moodTop[1]+'일':'기분도 천천히 남겨 봐'}</span></div><div><strong>나만</strong><span>일기는 기본 비공개</span></div></div><div class="diary-layout"><section class="diary-calendar"><div class="life-toolbar"><button class="ghost" id="diary-prev" aria-label="이전 달">←</button><input type="month" id="diary-month" aria-label="일기 월 선택" value="${diaryMonth}"><button class="ghost" id="diary-next" aria-label="다음 달">→</button></div><div class="diary-days">${['일','월','화','수','목','금','토'].map(d=>'<span>'+d+'</span>').join('')}${'<span></span>'.repeat(first)}${Array.from({length:days},(_,i)=>{const date=diaryMonth+'-'+String(i+1).padStart(2,'0'),r=diaryFind(date);return `<button class="diary-day ${r?'has-diary':''} ${date===lifeDate()?'today':''}" data-day="${date}" aria-label="${date}${r?' 일기 읽기':' 일기 쓰기'}"><b>${i+1}</b><span>${r?(diaryMoods[r.diary?.mood]||'●'):''}</span></button>`;}).join('')}</div><p class="app-status">날짜를 누르면 그날의 일기를 펼칠 수 있어요.</p><button class="ghost wide" id="diary-connect">Notion 저장 연결</button></section><section><div class="life-toolbar"><input id="diary-search" aria-label="일기 검색" placeholder="다시 찾고 싶은 말…" value="${lifeText(diaryQuery)}"><select id="diary-mood-filter" aria-label="기분으로 찾기"><option value="">모든 기분</option>${Object.entries(diaryMoods).map(([m,e])=>`<option ${m===diaryMood?'selected':''}>${m}</option>`).join('')}</select></div><div class="diary-list">${rows.map(r=>`<button class="diary-entry" data-diary="${lifeText(r.id)}"><span>${lifeText(r.when)} · ${diaryMoods[r.diary?.mood]||'📓'} ${lifeText(r.diary?.mood||'')}</span><h3>${lifeText(r.title)}</h3><p>${lifeText((r.diary?.thoughts||r.diary?.events||r.body).slice(0,120))}</p><small>${r.notion?.url?'Notion에 저장된 기록':'기기에 저장됨'}</small></button>`).join('')||'<div class="empty-state">아직 남긴 일기가 없어요.<br>날짜를 눌러 한 문장부터 시작해 봐요.</div>'}</div></section></div>`;
 $('#diary-today').onclick=()=>diaryForm(lifeDate());lifeShell.querySelectorAll('[data-day]').forEach(b=>b.onclick=()=>{const r=diaryFind(b.dataset.day);r?diaryRead(r.id):diaryForm(b.dataset.day);});lifeShell.querySelectorAll('[data-diary]').forEach(b=>b.onclick=()=>diaryRead(b.dataset.diary));$('#diary-month').onchange=e=>{if(/^\d{4}-\d{2}$/.test(e.target.value)){diaryMonth=e.target.value;diaryRender();}};for(const [id,delta] of [['diary-prev',-1],['diary-next',1]])$('#'+id).onclick=()=>{const d=new Date(year,month-1+delta,1);diaryMonth=d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0');diaryRender();};$('#diary-mood-filter').onchange=e=>{diaryMood=e.target.value;diaryRender();};$('#diary-search').oninput=e=>{const pos=e.target.selectionStart;diaryQuery=e.target.value;diaryRender();$('#diary-search').focus();$('#diary-search').setSelectionRange(pos,pos);};$('#diary-connect').onclick=diaryConnection;
}
function diaryKeepDraft(){const f=$('#diary-form');if(!f)return;clearTimeout(diaryDraftTimer);try{const v=Object.fromEntries(new FormData(f));localStorage.setItem(diaryDraftKey(diaryDate),JSON.stringify(v));$('#diary-save-state').textContent='작성 중인 글을 이 기기에 임시 보관했어요.';}catch{if($('#diary-save-state'))$('#diary-save-state').textContent='임시 보관하지 못했어요. 아래 저장 버튼으로 남겨 주세요.';}}
window.addEventListener('pagehide',()=>{if(diaryWriting)diaryKeepDraft();});lifeDialog.addEventListener('close',()=>{if(diaryWriting)diaryKeepDraft();diaryWriting=false;});
function diaryForm(date){clearTimeout(diaryDraftTimer);diaryDate=date;const existing=diaryFind(date);let draft;try{draft=JSON.parse(localStorage.getItem(diaryDraftKey(date)));}catch{}const d=draft||{title:existing?.title||'',...existing?.diary};diaryPhoto=existing?.photo||'';lifeEditing=null;lifeEditorDirty=false;diaryWriting=true;
 lifeShow(`<div class="eyebrow">MY PERSONAL DIARY</div><h2>${lifeText(date)}의 나</h2><form id="diary-form"><label class="field">날짜<input type="date" id="diary-date" value="${date}" required></label><label class="field">오늘을 한 문장으로<input name="title" maxlength="180" value="${lifeText(d.title)}" placeholder="오늘은 어떤 하루였어? 비워 두어도 좋아."></label><fieldset class="diary-moods"><legend>지금의 기분</legend>${Object.entries(diaryMoods).map(([m,e])=>`<label><input type="radio" name="mood" value="${m}" ${d.mood===m?'checked':''}><span>${e} ${m}</span></label>`).join('')}</fieldset>${[['events','오늘 있었던 일','누구를 만났고, 무엇을 했어?'],['thoughts','내 마음과 생각','그때 어떤 마음이 들었어? 정리되지 않아도 괜찮아.'],['gratitude','고마웠던 것','작은 기쁨이나 다정했던 순간 하나'],['tomorrow','내일의 나에게','내일 해보고 싶은 일, 나에게 건네는 말']].map(([key,label,placeholder])=>`<label class="field">${label}<textarea name="${key}" maxlength="25000" placeholder="${placeholder}">${lifeText(d[key])}</textarea></label>`).join('')}<div class="life-note">이 일기는 나만 간직하는 기록으로 저장돼요. Notion에 연결하기 전에도 글은 이 기기에 남길 수 있어요.</div>${sessionStorage.getItem(lifeKey('diary-code'))?'<label class="check-label"><input type="checkbox" name="sendNotion" '+(localStorage.getItem(lifeKey('diary-auto'))==='yes'?'checked':'')+'> 저장할 때 Notion 개인 일기장에도 보내기</label>':''}<div class="actions"><button class="primary" id="diary-save">일기 저장</button><button class="ghost" type="button" id="diary-draft-save">임시 보관</button></div><div class="save-state" id="diary-save-state" role="status">${draft?'작성하던 글을 불러왔어요.':existing?'저장했던 일기를 수정하고 있어요.':''}</div></form>`);
 const f=$('#diary-form');f.oninput=()=>{clearTimeout(diaryDraftTimer);diaryDraftTimer=setTimeout(diaryKeepDraft,500);};$('#diary-draft-save').onclick=diaryKeepDraft;$('#diary-date').onchange=e=>{if(!e.target.value)return;diaryKeepDraft();diaryForm(e.target.value);};
 f.onsubmit=async e=>{e.preventDefault();clearTimeout(diaryDraftTimer);const v=Object.fromEntries(new FormData(f));const d={mood:v.mood||'',events:v.events.trim(),thoughts:v.thoughts.trim(),gratitude:v.gratitude.trim(),tomorrow:v.tomorrow.trim()};const body=diaryBody(d);if(!body){$('#diary-save-state').textContent='오늘의 이야기를 한 문장이라도 남겨 주세요.';return;}const r={...existing,id:existing?.id||lifeID(),home:lifeHome.id,kind:'diary',title:v.title.trim()||diaryDate+'의 일기',when:diaryDate,body,diary:d,share:false,photo:diaryPhoto,comments:[],created:existing?.created||new Date().toISOString(),updated:new Date().toISOString()};if(existing?.notion?.url)r.notion={...existing.notion,changed:true};$('#diary-save').disabled=true;try{await lifePut(r);localStorage.removeItem(diaryDraftKey(diaryDate));diaryWriting=false;lifeDialog.close();await lifeRefresh();diaryMonth=diaryDate.slice(0,7);diaryRender();diaryRead(r.id);toast('일기를 내 서버 공간에 저장했어요.');if(f.elements.sendNotion?.checked)await diaryTransfer(r);}catch{$('#diary-save-state').textContent='저장하지 못했어요. 내용을 복사해 두고 기기 저장 공간을 확인해 주세요.';$('#diary-save').disabled=false;}};
}
function diaryRead(id){const r=lifeRecords.find(r=>r.id===id);if(!r)return;diaryWriting=false;lifeEditing=null;lifeEditorDirty=false;const d=r.diary||{};lifeShow(`<div class="eyebrow">${lifeText(r.when)} · PRIVATE</div><h2>${lifeText(r.title)}</h2><p>${diaryMoods[d.mood]||'📓'} ${lifeText(d.mood||'오늘의 기록')}</p>${[['events','오늘 있었던 일'],['thoughts','내 마음과 생각'],['gratitude','고마웠던 것'],['tomorrow','내일의 나에게']].filter(([k])=>d[k]).map(([k,title])=>`<h3>${title}</h3><div class="life-reading">${lifeText(d[k])}</div>`).join('')||'<div class="life-reading">'+lifeText(r.body)+'</div>'}<div class="life-note" style="margin-top:25px">${r.notion?.url?(r.notion.changed?'Notion 저장 이후 수정된 내용이 있어요.':'Notion 기록 주소가 연결되어 있어요.'):'내 서버 공간에 저장되어 있어요. 아직 Notion에 저장된 것으로 확인되지 않았어요.'}</div><div class="actions"><button class="primary" id="diary-to-notion">Notion에 저장하기</button><button class="ghost" id="diary-edit">일기 다듬기</button><button class="ghost" id="diary-md">글 파일로 보관</button><button class="ghost danger" id="diary-trash">휴지통으로</button></div><p class="app-status">일기 내용은 공개 웹사이트 코드나 가족 앨범에 자동으로 포함되지 않아요.</p>`);$('#diary-edit').onclick=()=>diaryForm(r.when);$('#diary-to-notion').onclick=()=>diaryTransfer(r);$('#diary-md').onclick=()=>lifeDownload(r.when+'-일기.md',diaryMarkdown(r),'text/markdown;charset=utf-8');$('#diary-trash').onclick=async()=>{await lifePut({...r,deleted:true});lifeDialog.close();await lifeRefresh();diaryRender();toast('일기를 휴지통으로 옮겼어요.');};
}
function diaryConnection(){let target='';try{target=localStorage.getItem(lifeKey('notion-diary-url'))||'';}catch{}lifeShow(`<div class="eyebrow">DIARY → NOTION</div><h2>내 개인 일기장에 이어 쓰기</h2><p>Notion 일기장 주소를 저장하면 바로 열 수 있어요. 주소만 연결하는 것은 자동 저장 권한을 연결하는 것과 달라요.</p><form id="diary-target-form"><label class="field">Notion 개인 일기장 주소<input type="url" name="url" value="${lifeText(target)}" placeholder="https://www.notion.so/…" required></label><button class="primary">일기장 주소 저장</button></form><div class="life-note" style="margin-top:20px">현재 자동 저장 인증 서버는 연결되지 않았어요. 이 채팅의 Notion 연결을 통해 정리한 일기를 옮길 수 있고, 앱에서는 복사용 글과 전달 파일을 준비할 수 있어요. 자동 연결이 완료되기 전에는 Notion 저장 완료라고 표시하지 않습니다.</div>`);$('#diary-target-form').onsubmit=e=>{e.preventDefault();const u=safeURL(new FormData(e.target).get('url'));if(!u){toast('올바른 주소를 넣어 주세요.');return;}const host=new URL(u).hostname;if(!['notion.so','www.notion.so','app.notion.com','notion.site'].includes(host)&&!host.endsWith('.notion.site')){toast('Notion 일기장 주소를 넣어 주세요.');return;}localStorage.setItem(lifeKey('notion-diary-url'),u);lifeDialog.close();toast('일기장 주소를 이 기기에 저장했어요. 자동 저장 연결은 아직 남아 있어요.');};}
function diaryTransfer(r){let target=localStorage.getItem(lifeKey('notion-diary-url'))||'';lifeShow(`<div class="eyebrow">NOTION SAVE PREPARATION</div><h2>Notion에 옮길 일기</h2><p>일기는 기기에 저장되어 있어요. 아직 자동 저장 인증은 연결되지 않았어요.</p><label class="field">정리된 일기<textarea id="diary-transfer-text" readonly>${lifeText(diaryMarkdown(r))}</textarea></label><div class="actions"><button class="primary" id="diary-copy">일기 복사</button>${safeURL(target)?linkButton(target,'Notion 개인 일기장 열기'):'<button class="ghost" id="diary-target">개인 일기장 주소 연결</button>'}<button class="ghost" id="diary-request">이 채팅에 전달할 파일 만들기</button></div><p>복사한 글은 Notion 개인 일기장에 직접 붙여넣을 수 있어요. 또는 전달 파일을 이 채팅에 첨부하면 내가 기존 일기장의 날짜·개인·일기 분류에 맞춰 저장할 수 있어요. 파일을 만드는 것만으로 Notion에 저장되지는 않습니다.</p><div id="diary-transfer-status" class="save-state" role="status"></div>`);$('#diary-copy').onclick=async()=>{try{await navigator.clipboard.writeText(diaryMarkdown(r));$('#diary-transfer-status').textContent='글을 복사했어요. Notion에 붙여넣어 주세요.';}catch{$('#diary-transfer-text').select();$('#diary-transfer-status').textContent='위 글을 길게 눌러 복사해 주세요.';}};if($('#diary-target'))$('#diary-target').onclick=diaryConnection;$('#diary-request').onclick=()=>lifeDownload(r.when+'-Notion에-저장할-일기.json',JSON.stringify({format:'life-notion-diary-request',version:1,entry:{id:r.id,title:r.title,date:r.when,body:r.body,mood:r.diary?.mood||'',tags:['개인','일기'],updated:r.updated}}),'application/json');}

const diaryBasicConnection=diaryConnection,diaryManualTransfer=diaryTransfer;
diaryConnection=function(){diaryBasicConnection();const endpoint=localStorage.getItem(lifeKey('diary-server'))||'';const box=document.createElement('section');box.innerHTML=`<hr style="border:0;border-top:1px solid var(--line);margin:25px 0"><h3>앱 전용 저장 서버 연결</h3><p>저장 서버와 Notion 권한 승인이 준비된 뒤 연결할 수 있어요. Notion 비밀키를 여기에 넣지 마세요.</p><form id="diary-server-form"><label class="field">저장 서버 주소<input type="url" name="endpoint" value="${lifeText(endpoint)}" placeholder="https://…workers.dev" required></label><label class="field">앱 연결 코드<input type="password" name="code" autocomplete="off" minlength="32" required placeholder="저장 서버에서 발급한 연결 코드"></label><button class="primary">연결 확인</button><button class="ghost" type="button" id="diary-disconnect">연결 해제</button><p id="diary-server-status" role="status"></p></form>`;$('#life-content').append(box);$('#diary-disconnect').onclick=()=>{sessionStorage.removeItem(lifeKey('diary-code'));localStorage.removeItem(lifeKey('diary-server'));$('#diary-server-status').textContent='저장 서버 연결을 해제했어요. 저장했던 일기는 남아 있어요.';};$('#diary-server-form').onsubmit=async e=>{e.preventDefault();const f=e.target,v=new FormData(f);let url;try{url=new URL(v.get('endpoint'));if(url.protocol!=='https:'||url.username||url.password||url.search||url.hash)throw Error();}catch{$('#diary-server-status').textContent='https로 시작하는 저장 서버 주소를 넣어 주세요.';return;}const endpoint=url.origin,code=String(v.get('code'));f.querySelector('button').disabled=true;try{const response=await fetch(endpoint+'/health',{headers:{Authorization:'Bearer '+code},signal:AbortSignal.timeout(15000)}),result=await response.json();if(!response.ok||result.ready!==true)throw Error();localStorage.setItem(lifeKey('diary-server'),endpoint);sessionStorage.setItem(lifeKey('diary-code'),code);localStorage.setItem(lifeKey('diary-auto'),'yes');f.elements.code.value='';$('#diary-server-status').textContent='Notion 일기장 접근을 확인했어요. 이제 일기에서 Notion에 저장하기를 누를 수 있어요.';}catch{$('#diary-server-status').textContent='연결을 확인하지 못했어요. 서버와 연결 코드, Notion 일기장 공유 권한을 확인해 주세요.';}finally{f.querySelector('button').disabled=false;}};};
diaryTransfer=async function(r){const endpoint=localStorage.getItem(lifeKey('diary-server')),code=sessionStorage.getItem(lifeKey('diary-code'));if(!endpoint||!code){diaryManualTransfer(r);const connect=document.createElement('button');connect.className='ghost';connect.textContent='자동 저장 연결 설정';connect.onclick=diaryConnection;$('#life-content').append(connect);return;}lifeShow('<h2>Notion에 일기 저장 중</h2><p>원문은 이 기기에 남아 있어요. 저장 결과를 확인하고 있어요.</p><p id="notion-save-status" role="status">저장 중…</p>');try{const response=await fetch(endpoint+'/diary',{method:'POST',headers:{Authorization:'Bearer '+code,'Content-Type':'application/json'},body:JSON.stringify({id:lifeHome.id+':'+r.id,title:r.title,date:r.when,body:r.body,mood:r.diary?.mood||''}),signal:AbortSignal.timeout(25000)});const result=await response.json();if(!response.ok||result.status!=='saved'||!/^https:\/\/(www\.notion\.so|notion\.so|app\.notion\.com)\//.test(result.url||''))throw Error(result.error||'unconfirmed');const latest=(await lifeAll()).find(x=>x.id===r.id&&x.home===lifeHome.id);if(latest)await lifePut({...latest,notion:{url:result.url,savedAt:new Date().toISOString(),changed:latest.updated!==r.updated}});await lifeRefresh();if($('#notion-save-status')){$('#notion-save-status').textContent='Notion 저장을 확인했어요.';$('#life-content').insertAdjacentHTML('beforeend',linkButton(result.url,'저장된 Notion 일기 열기'));}toast('Notion 개인 일기장에 저장했어요.');}catch(error){if($('#notion-save-status'))$('#notion-save-status').textContent=error.message==='previous_save_needs_review'?'이전 저장 결과를 확인해야 해요. 중복 생성을 막기 위해 다시 만들지 않았어요.':'Notion 저장이 확인되지 않았어요. 기기의 일기는 그대로 남아 있어요. 연결 상태와 Notion을 확인한 뒤 다시 시도해 주세요.';}};

if('serviceWorker' in navigator&&location.protocol!=='file:')navigator.serviceWorker.register('./sw.js').catch(()=>{});






