window.lifeKeepRoomViewport=function(){const left=window.scrollX,top=window.scrollY;return ()=>{canvas.focus({preventScroll:true});window.scrollTo({left,top,behavior:'auto'});requestAnimationFrame(()=>window.scrollTo({left,top,behavior:'auto'}));};};
